// Read-only source; measure mounting contact on a disposable copy.
using System;using System.IO;using System.Linq;using System.Globalization;using System.Collections.Generic;
using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro {public static class LatchInProcess {
static JavaScriptSerializer J=new JavaScriptSerializer();
public static int Run(string folder){IZDoc owned=null;var report=new Dictionary<string,object>();bool pass=false;try{var r=(Dictionary<string,object>)J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(r["expected_pid"])||(string)r["contract"]!="rockpro-clearance-probe-v1")throw new Exception("Wrong host");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;string copy=Path.Combine(folder,"probe-copy.ics");File.Copy((string)r["file"],copy,false);bool already;owned=app.OpenFile2(copy,false,false,out already);if(already){owned=null;throw new Exception("Ownership failure");}var s=(IZSceneDoc)owned;var u=(IZSceneDocUtility)s;var results=new List<object>();foreach(object raw in (object[])r["pairs"]){var pair=(Dictionary<string,object>)raw;var e=u.GetElementById(Convert.ToInt32(pair["hardware"]));var target=(IZPart)u.GetElementById(Convert.ToInt32(pair["target"]));var se=(IZSceneElement)e;int axis=Convert.ToInt32(pair["axis"]);double initial=se.GetTransformToParent().GetValue(3,axis)*1000;string original=se.ParameterMgr.GetParameterByName("RP_Polozenie"+"XYZ"[axis]).Expression;var samples=new List<object>();foreach(double offset in new[]{0,.01,.1,.5,1.2,3.0}){se.ParameterMgr.GetParameterByName("RP_Polozenie"+"XYZ"[axis]).Expression=(initial-offset).ToString("R",CultureInfo.InvariantCulture)+" mm";s.Update();bool collision=target.HasInterference(e);samples.Add(new{offset_mm=offset,collision=collision});if(!collision)break;}se.ParameterMgr.GetParameterByName("RP_Polozenie"+"XYZ"[axis]).Expression=original;s.Update();results.Add(new{key=pair["key"],samples=samples});}report["results"]=results;owned.Close2(true);owned=null;pass=true;}catch(Exception ex){report["error"]=ex.ToString();}finally{if(owned!=null)try{owned.Close2(true);}catch{}report["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(report));}return pass?0:1;}
}}
